import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        TreeNode root = readTree(new Scanner(System.in));
        System.out.println("Height: " + height(root));
        System.out.println("Sum: " + sum(root));
        System.out.println("Max: " + max(root));
        System.out.println("Leaves: " + leaves(root));
    }

    // Finished helper: reads level-order values (-1 means no child) and builds the tree.
    static TreeNode readTree(Scanner sc) {
        TreeNode dummy = new TreeNode(0); // the first value becomes dummy.right
        Queue<TreeNode> parents = new ArrayDeque<>();
        parents.offer(dummy);
        for (int i = 0; sc.hasNextInt() && !parents.isEmpty(); i++) {
            int value = sc.nextInt();
            TreeNode node = value == -1 ? null : new TreeNode(value);
            if (i % 2 == 1) {
                parents.peek().left = node;
            } else {
                parents.poll().right = node;
            }
            if (node != null) {
                parents.offer(node);
            }
        }
        return dummy.right;
    }

    static int height(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + Math.max(height(node.left), height(node.right));
    }

    static int sum(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return node.val + sum(node.left) + sum(node.right);
    }

    static int max(TreeNode node) {
        if (node == null) {
            return Integer.MIN_VALUE;
        }
        return Math.max(node.val, Math.max(max(node.left), max(node.right)));
    }

    static int leaves(TreeNode node) {
        if (node == null) {
            return 0;
        }
        if (node.left == null && node.right == null) {
            return 1;
        }
        return leaves(node.left) + leaves(node.right);
    }
}

