        TreeNode root = readTree(new Scanner(System.in));
        List<List<Integer>> levels = levelOrder(root);
        for (int i = 0; i < levels.size(); i++) {
            System.out.println("Level " + (i + 1) + ": " + levels.get(i));
        }
