        TreeNode root = null;
        for (int i = 0; i < n; i++) {
            root = insert(root, sc.nextInt());
        }
        int target = sc.nextInt();
        System.out.println("Min: " + min(root));
        System.out.println("Max: " + max(root));
        Integer above = smallestAbove(root, target);
        if (above == null) {
            System.out.println("Smallest above " + target + ": none");
        } else {
            System.out.println("Smallest above " + target + ": " + above);
        }
    }

    static TreeNode insert(TreeNode node, int val) {
        if (node == null) {
            return new TreeNode(val);
        }
        if (val < node.val) {
            node.left = insert(node.left, val);
        } else if (val > node.val) {
            node.right = insert(node.right, val);
        }
        return node;
    }

    static int min(TreeNode node) {
        while (node.left != null) {
            node = node.left;
        }
        return node.val;
    }

    static int max(TreeNode node) {
        while (node.right != null) {
            node = node.right;
        }
        return node.val;
    }

    static Integer smallestAbove(TreeNode node, int target) {
        Integer best = null;
        while (node != null) {
            if (node.val > target) {
                best = node.val;
                node = node.left;
            } else {
                node = node.right;
            }
        }
        return best;
    }
